using Tabletop.Protocol;
using Tabletop.Sim.Scenarios;

namespace Tabletop.Sim.Suite;

/// <summary>
/// The spells group (rules suite plan, Task 7): a game per book, generated by SpellGames, each casting every spell of its book by name.
/// One exact check per effect kind the spells use, on a spell whose text states it, each quoting that text; the expected values are the
/// text's own numbers. Every game plays seed 1: the script decides who casts what at whom; only Sky Blaze's natural 6 and the two morale
/// checks' pass and fail rest on the dice as the seed rolls them.
/// </summary>
public static partial class SuiteCatalog
{
    private static partial IEnumerable<TestGame> Spells() =>
        SpellGames.Books(ScenarioCompiler.CoreProperties).Select(book => SpellGames.Game(book, seed: 1,
            ScenarioCompiler.CoreProperties, SpellTables.Setups.GetValueOrDefault(book.Uid), SpellTables.Dice.GetValueOrDefault(book.Uid),
            SpellTables.Checks.GetValueOrDefault(book.Uid)) with { Known = SpellTables.Known.GetValueOrDefault(book.Uid) ?? [] })
        .Append(EditedCastingDie());

    public const string EditedCastingDieName = "spells-edited-casting-die";
    public const string EditedCastCheck = "edited casting die (p.13: \"Roll one die, on 4+ resolve the effect\"; p.5: \"a roll of 1 always counts as a fail\")";

    /// <summary>
    /// The Orc Marauders' spell game with its first casting roll, a pass as rolled, set to a raw 1 by SetDice once the roll step has
    /// completed: `result` reads the die as it now stands, so the cast must not resolve. Covers nothing of its own; the check reports
    /// against Caster.
    /// </summary>
    static TestGame EditedCastingDie()
    {
        var book = ScenarioCompiler.CoreProperties.Books["1wj1ysgxpuuz9bc7"];
        var game = SpellGames.Game(book, seed: 1, ScenarioCompiler.CoreProperties, dice: [new DiceFix("casting", 0, [1])]);
        return game with
        {
            Name = EditedCastingDieName,
            Scenario = game.Scenario with { Name = EditedCastingDieName },
            Covers = [],
            Checks = [Checks.Ended(), Checks.Invariants(), new GameCheck(EditedCastCheck, run => EditedCasts(LogQueries.Of(run), book.Spells), ["Caster"])],
        };
    }

    /// <summary>Every cast whose casting die an edit set to a raw 1 neither passed nor resolved its spell; at least one such cast.</summary>
    static string? EditedCasts(LogQueries q, IReadOnlyList<string> spells) => LogQueries.Each(
        spells.SelectMany(s => SpellGames.Casts(q, s).Select(c => (Spell: s, Cast: c))).Where(x => x.Cast.Roll.Edited && x.Cast.Die.Raw == 1),
        "cast on an edited raw 1",
        x => x.Cast.Passed || SpellGames.Resolved(q, x.Cast, x.Spell) ? $"{x.Spell} on an edited raw 1 (modified {x.Cast.Die.Modified}): passed {x.Cast.Passed}, resolved {SpellGames.Resolved(q, x.Cast, x.Spell)}" : null);

    /// <summary>
    /// The per-book tables, in a class of their own: SuiteCatalog.All is set by SuiteCatalog's static initializer, and the language fixes
    /// no order between the static fields of two partial files.
    /// </summary>
    static class SpellTables
    {
        /// <summary>Per book uid: how its game deviates from the default casting order, targets and target actions.</summary>
        public static readonly Dictionary<string, SpellSetup> Setups = new(StringComparer.Ordinal)
        {
            // Mutating Inferno first: no attack precedes it, so its first target's blocks are the game's defense roll 0.
            // Breath of Change on its caster's own unit every round: "Bane when Shooting" is never used (the book's army does not shoot), so
            // the second cast meets a unit still holding the first and must write nothing.
            ["04z57ua0bwth37zh"] = new(First: ["Mutating Inferno"],
                Targets: new Dictionary<string, Func<string, IReadOnlyList<string>>> { ["Breath of Change"] = caster => [caster] }),
            // Tech-Sickness first, at target unit 1, which every later enemy spell hits too.
            ["hk70l4d471plza00"] = new(First: ["Tech-Sickness"]),
            // Shock Speed on the next unit of the book's army, which moves next by Advance.
            ["3j10zage1lddt6sr"] = new(Targets: new Dictionary<string, Func<string, IReadOnlyList<string>>> { ["Shock Speed"] = NextUnit }),
            // Corrode Weapons first, at target unit 1, which Advances and shoots its AP(1) rifles every round.
            ["7el7k3hgy5pb9o9i"] = new(First: ["Corrode Weapons"],
                Targets: new Dictionary<string, Func<string, IReadOnlyList<string>>> { ["Corrode Weapons"] = _ => [SpellGames.UnitName(SpellGames.TargetArmy, 1)] },
                BlueAction: j => j == 1 ? "Advance" : "Rush"),
            // Cursed Stride first, at target unit 1 (the default enemy target).
            ["7o6om21wxlvvy3hq"] = new(First: ["Cursed Stride"]),
            // Every spare token on the roll (+3 to +5), so an unmodified 1 is lifted to 4+ and the natural casting die check has a case.
            ["z65fgu0l29i4lnlu"] = new(Bonus: 6),
        };

        /// <summary>Per book uid: the dice its exact checks fix (DiceFix: the roll kind's ordinal in the game, counted from zero).</summary>
        public static readonly Dictionary<string, IReadOnlyList<DiceFix>> Dice = new(StringComparer.Ordinal)
        {
            // The first target's blocks of Mutating Inferno, the game's first defense roll: three 1s and a 6 against Defense 4+.
            ["04z57ua0bwth37zh"] = [new DiceFix("defense", 0, [1, 1, 1, 6])],
        };

        /// <summary>Per book uid: the exact checks its game makes, one per effect kind the spells use across the group.</summary>
        public static readonly Dictionary<string, IReadOnlyList<GameCheck>> Checks = new(StringComparer.Ordinal)
        {
            ["z65fgu0l29i4lnlu"] = [Exact(NaturalCastingDieCheck, ["Caster"], NaturalCastingDice)],
            ["04z57ua0bwth37zh"] = [Exact(AddHitCheck, ["Mutating Inferno"], MutatingInferno), Exact(RolledHitsCheck, ["Sky Blaze"], SkyBlaze),
                Exact(GrantCheck, ["Breath of Change"], BreathOfChange)],
            ["hk70l4d471plza00"] = [Exact(RollModifierCheck, ["Tech-Sickness"], TechSickness)],
            ["3j10zage1lddt6sr"] = [Exact(StatCheck, ["Shock Speed"], ShockSpeed)],
            ["7el7k3hgy5pb9o9i"] = [Exact(ParameterCheck, ["Corrode Weapons"], CorrodeWeapons)],
            ["7o6om21wxlvvy3hq"] = [Exact(TerrainCheck, ["Cursed Stride"], CursedStride)],
            ["31xjrm9ivdimkjxp"] = [Exact(FatiguedCheck, ["Terrifying Fury"], TerrifyingFury)],
            ["zz3kp5ry7ks6mxcx"] = [Exact(MoveCheck, ["Deep Hypnosis"], DeepHypnosis)],
        };

        /// <summary>Per book uid: the engine defects its game is pinned to.</summary>
        public static readonly Dictionary<string, IReadOnlyList<KnownDefect>> Known = new(StringComparer.Ordinal)
        {
            ["z65fgu0l29i4lnlu"] = [new KnownDefect("D9", NaturalCastingDieCheck, "raw 1, modified 5: judged a success")],
        };

        /// <summary>The unit after the caster's in the book's army, wrapping: "&lt;army&gt; unit k" → "&lt;army&gt; unit k+1".</summary>
        static IReadOnlyList<string> NextUnit(string caster)
        {
            var cut = caster.LastIndexOf(' ');
            var k = int.Parse(caster[(cut + 1)..]);
            return [$"{caster[..cut]} {k % 6 + 1}"];
        }
    }

    public const string NaturalCastingDieCheck = "casting die (p.5: \"a roll of 6 always counts as a success and a roll of 1 always counts as a fail, regardless of how much it is being modified by\")";
    public const string AddHitCheck = "add_hit (Mutating Inferno: \"which take 4 hits each\"; p.9: \"all failed rolls cause one wound each\")";
    public const string RolledHitsCheck = "add_hit rolled (Sky Blaze: \"takes 2 hits with AP(1) and Surge. Roll as many dice as hits\"; p.14 Surge: \"On unmodified results of 6 to hit, this weapon deals 1 extra hit\"; p.13 AP(X): \"Targets get -X to Defense rolls\")";
    public const string GrantCheck = "grant_property (Breath of Change: \"Pick up to two friendly units within 12\\\", which get Bane when Shooting once\"; p.13: \"Effects from multiple instances of the same special rule or spell don't stack\")";
    public const string RollModifierCheck = "modify_roll (Tech-Sickness: \"which get -1 to defense rolls once (next time the effect would apply)\")";
    public const string StatCheck = "modify_stat (Shock Speed: \"moves +2\\\" when using Advance actions and +4\\\" when using Rush/Charge actions once\"; p.7: Advance \"up to 6”\")";
    public const string ParameterCheck = "modify_parameter (Corrode Weapons: \"which loses AP(1) when shooting once\"; p.13 AP(X): \"Targets get -X to Defense rolls\")";
    public const string TerrainCheck = "count_as_terrain (Cursed Stride: \"counts as being in Dangerous Terrain once\"; p.11: \"or is activated in it, then it must take a dangerous terrain test ... roll one die (or as many dice as the model’s Tough value)\")";
    public const string FatiguedCheck = "take_test, set_condition (Terrifying Fury: \"must take a morale test. If failed, it becomes fatigued\"; p.10: \"If the test is failed, the unit is Shaken\")";
    public const string MoveCheck = "take_test, move (Deep Hypnosis: \"must take a morale test. If failed you may move it by up to 6\\\" in a straight line\")";

    static GameCheck Exact(string name, string[] entries, Func<LogQueries, string?> failure) => new(name, run => failure(LogQueries.Of(run)), entries);

    /// <summary>
    /// Every casting die as rolled, judged by p.5 alone: an unmodified 1 a failure, an unmodified 6 a success. The cases are the dice whose
    /// modifiers would carry them the other way, and at least one must occur (this game spends every spare token on its rolls, so a raw 1
    /// lifted to 4+ comes up). No die is edited: the check is about the judge, not about dice edits.
    /// </summary>
    static string? NaturalCastingDice(LogQueries q) => LogQueries.Each(
        q.Rolls("casting").Where(r => !r.Edited).Select(r => r.Dice[0]).Where(d => d.Raw == 1 && d.Modified >= 4 || d.Raw == 6 && d.Modified < 4),
        "unmodified 1 lifted to 4+ (or 6 dropped below it)",
        d => d.Success == (d.Raw == 6) ? null : $"raw {d.Raw}, modified {d.Modified}: judged a {(d.Success ? "success" : "failure")}");

    /// <summary>The spell-hits frames of a spell's resolved casts, each with its hit step, its score-hits step and its resolve-hits' block rolls.</summary>
    static IReadOnlyList<(LoggedFrame Hits, LoggedStep Hit, LoggedStep Score, IReadOnlyList<LoggedRoll> Blocks)> SpellHits(LogQueries q, string spell) =>
        [.. SpellGames.Casts(q, spell).Where(c => c.Passed).SelectMany(c => q.Children(c.Frame).Where(f => f.Sequence == "spell-hits")).Select(h =>
            (h, h.Steps.Single(s => s.Name == "hit"), h.Steps.Single(s => s.Name == "score-hits"),
             (IReadOnlyList<LoggedRoll>)[.. q.Children(h).Where(r => r.Sequence == "resolve-hits").SelectMany(r => r.Steps)
                 .Where(s => s.Name == "roll-to-block").SelectMany(s => s.Rolls("defense"))]))];

    /// <summary>The wounds a frame's deal-wounds dealt: each frame's last assign (its wounds_dealt is the frame's running total).</summary>
    static int Dealt(LogQueries q, LoggedFrame frame) =>
        q.Descendants(frame).Where(f => f.Sequence == "deal-wounds").Sum(f => f.Steps.LastOrDefault(s => s.Name == "assign")?.Value("wounds_dealt") ?? 0);

    /// <summary>
    /// Mutating Inferno: each target takes 4 hits with no die rolled for them and rolls 4 blocks. The game's first defense roll is its first
    /// target's blocks, fixed to [1,1,1,6]: 3 failed blocks, 3 wounds.
    /// </summary>
    static string? MutatingInferno(LogQueries q)
    {
        var hits = SpellHits(q, "Mutating Inferno");
        var first = q.Rolls("defense").FirstOrDefault();
        if (first is null || !first.Edited) return "the fixed block roll never happened";
        if (first.Frame.Nearest("spell-hits") is not { } fixedHits || !hits.Any(h => h.Hits == fixedHits)) return "the game's first block roll is not Mutating Inferno's";
        if (first.Dice.Count(d => !d.Success) != 3) return $"the fixed blocks {LogQueries.Show(first)} are not 3 failures";
        if (Dealt(q, fixedHits) != 3) return $"the fixed blocks dealt {Dealt(q, fixedHits)} wounds, not 3";
        return LogQueries.Each(hits, "Mutating Inferno target", h =>
            h.Hit.AllRolls.Count > 0 ? $"the hits rolled {h.Hit.AllRolls.Count} rolls; the text rolls none"
            : h.Hit.Value("hits") != 4 ? $"hits {h.Hit.Value("hits")}, not 4"
            : h.Blocks.Sum(r => r.Dice.Count) != 4 ? $"{h.Blocks.Sum(r => r.Dice.Count)} blocks rolled for 4 hits" : null);
    }

    /// <summary>
    /// Sky Blaze: 2 hits, one die each at no threshold to fail; each unmodified 6 adds a hit; every block is at AP(1). Read from the dice as
    /// they stand, which score-hits read.
    /// </summary>
    static string? SkyBlaze(LogQueries q)
    {
        var hits = SpellHits(q, "Sky Blaze");
        var failure = LogQueries.Each(hits, "Sky Blaze target", h =>
        {
            if (h.Hit.Rolls("hit").SingleOrDefault() is not { Dice.Count: 2 } roll) return "did not roll 2 dice for 2 hits";
            if (roll.Dice.Any(d => !d.Success)) return $"a spell hit die failed: {LogQueries.Show(roll)}";
            var sixes = roll.Raw(6);
            if (h.Score.Value("extra_hits") != sixes) return $"{LogQueries.Show(roll)} gave {h.Score.Value("extra_hits")} extra hits";
            if (h.Blocks.Sum(r => r.Dice.Count) != 2 + sixes) return $"{h.Blocks.Sum(r => r.Dice.Count)} blocks rolled for {2 + sixes} hits";
            return h.Blocks.FirstOrDefault(r => !r.Roll.Modifiers.Contains(new RollModifier("AP", -1))) is { } bare ? $"a block without AP -1: {LogQueries.Show(bare)}" : null;
        });
        return failure ?? (hits.Any(h => h.Score.Value("extra_hits") > 0) ? null : "no Sky Blaze die rolled a 6; the seed must show Surge");
    }

    /// <summary>Breath of Change on the caster's own unit every round: one grant on a target that holds none; none on one that still holds it.</summary>
    static string? BreathOfChange(LogQueries q)
    {
        var casts = SpellGames.Casts(q, "Breath of Change").Where(c => c.Passed).ToList();
        var cases = casts.SelectMany(c => c.Targets.Select(t => (Cast: c, Target: t, Held: Held(q, t, "Breath of Change", c.Frame.Seq)))).ToList();
        if (cases.All(c => !c.Held) || cases.All(c => c.Held)) return $"{cases.Count(c => c.Held)} of {cases.Count} targets already held the spell; the script recasts on one target so both happen";
        return LogQueries.Each(cases, "Breath of Change target", c =>
        {
            if (q.Final.Units[c.Target].ParticipantId != q.Final.Units[c.Cast.Unit].ParticipantId) return "an enemy unit was a target";
            var written = c.Cast.Grants.Count(g => g.UnitId == c.Target && g.Grant.EntryName == "Breath of Change");
            return written == (c.Held ? 0 : 1) ? null : $"{written} grants on a target that {(c.Held ? "already held" : "did not hold")} the spell";
        });
    }

    /// <summary>Whether a unit holds a grant of that spell before a seq: added and not yet removed.</summary>
    static bool Held(LogQueries q, Guid unit, string spell, long before)
    {
        var live = new HashSet<Guid>();
        foreach (var step in q.Steps.TakeWhile(s => s.Seq < before))
            foreach (var change in step.Step.Changes)
                if (change is GrantAdded a && a.UnitId == unit && a.Grant.EntryName == spell) live.Add(a.Grant.Id);
                else if (change is GrantRemoved r && r.UnitId == unit) live.Remove(r.GrantId);
        return live.Count > 0;
    }

    /// <summary>The first grant of a spell (that passes the filter), with the step that wrote it.</summary>
    static (LoggedStep Step, GrantAdded Grant)? FirstGrant(LogQueries q, string spell, Func<GrantAdded, bool>? where = null) =>
        q.Steps.SelectMany(s => s.Step.Changes.OfType<GrantAdded>().Where(g => g.Grant.EntryName == spell && (where?.Invoke(g) ?? true)).Select(g => (s, g)))
            .Cast<(LoggedStep, GrantAdded)?>().FirstOrDefault();

    /// <summary>Tech-Sickness: the target's next block roll is at -1, and that step spends the grant.</summary>
    static string? TechSickness(LogQueries q)
    {
        if (FirstGrant(q, "Tech-Sickness") is not var (at, grant)) return "Tech-Sickness never granted";
        var block = q.Steps.FirstOrDefault(s => s.Seq > at.Seq && s.Name == "roll-to-block" && s.Frame.Context.TargetUnitIds.FirstOrDefault() == grant.UnitId && s.Rolls("defense").Any());
        if (block is null) return "the target never rolled to block after the grant";
        var mods = block.Rolls("defense").SelectMany(r => r.Roll.Modifiers).Where(m => m.Source == "Tech-Sickness").ToList();
        if (mods.Count == 0 || mods.Any(m => m.Amount != -1)) return $"the next block's Tech-Sickness modifiers: [{string.Join(", ", mods.Select(m => m.Amount))}]";
        return block.Step.Changes.OfType<GrantRemoved>().Any(r => r.GrantId == grant.Grant.Id) ? null : "the block that used the grant did not remove it";
    }

    /// <summary>Shock Speed on another unit of the caster's army: that unit's next action move, an Advance, allows 6 + 2 = 8".</summary>
    static string? ShockSpeed(LogQueries q)
    {
        var casters = SpellGames.Casts(q, "Shock Speed").Select(c => c.Unit).ToHashSet();
        if (FirstGrant(q, "Shock Speed", g => !casters.Contains(g.UnitId)) is not var (at, grant)) return "Shock Speed never granted to a unit other than its caster's";
        var ask = q.Asks.FirstOrDefault(a => a.Seq > at.Seq && a.Ask.Question == "move" && a.Ask.Legal is MoveRegion r
            && r.ModelIds.All(m => q.UnitOf(m) == grant.UnitId) && a.Frame?.Sequence is "advance" or "rush" or "charge");
        if (ask is null) return "the unit never moved by an action after the grant";
        if (ask.Frame!.Sequence != "advance") return $"the unit's next move was a {ask.Frame.Sequence}, not the scripted Advance";
        var allowance = ((MoveRegion)ask.Ask.Legal).Allowance;
        return Math.Abs(allowance - 8) < 0.001 ? null : $"Advance allowance {allowance}\", expected 8\"";
    }

    /// <summary>
    /// Corrode Weapons: the target's first shooting blocks after the grant come from its AP(1) rifles and are rolled at no AP, in a step that
    /// names the spell. A block from a weapon without AP proves nothing, so it fails the check.
    /// </summary>
    static string? CorrodeWeapons(LogQueries q)
    {
        if (FirstGrant(q, "Corrode Weapons") is not var (at, grant)) return "Corrode Weapons never granted";
        var corroded = q.Steps.FirstOrDefault(s => s.Seq > at.Seq && s.Name == "roll-to-block" && s.Rolls("defense").Any()
            && s.Frame.Context.ActorUnitId == grant.UnitId && s.Frame.Nearest("shooting") is not null);
        if (corroded is null) return "the target never shot a hit home after the grant";
        var weapons = corroded.Frame.Context.WeaponIds.Select(id => q.Final.Models.Values.SelectMany(m => m.Slot.Weapons).First(w => w.Id == id)).ToList();
        if (weapons.Count == 0 || weapons.Any(w => !w.Properties.Contains(new Tabletop.Content.PropertyInstance("AP", 1))))
            return $"the corroded blocks came from {string.Join(", ", weapons.Select(w => w.Name))}, not only AP(1) weapons";
        var ap = corroded.Rolls("defense").SelectMany(r => r.Roll.Modifiers).Where(m => m.Source == "AP" && m.Amount != 0).ToList();
        if (ap.Count > 0) return $"the corroded blocks carry AP {string.Join(", ", ap.Select(m => m.Amount))}";
        return corroded.Lists("Corrode Weapons") ? null : "the corroded block's step does not name Corrode Weapons";
    }

    static readonly IReadOnlySet<string> RootActions = new HashSet<string> { "hold", "advance", "rush", "charge", "idle" };

    /// <summary>Cursed Stride: the target's next activation tests every living model at its Tough value in dice, 6 each.</summary>
    static string? CursedStride(LogQueries q)
    {
        if (FirstGrant(q, "Cursed Stride") is not var (at, grant)) return "Cursed Stride never granted";
        var activation = q.Frames.FirstOrDefault(f => f.Seq > at.Seq && RootActions.Contains(f.Sequence) && f.Context.ActorUnitId == grant.UnitId);
        if (activation is null) return "the target never activated after the grant";
        var test = q.Descendants(activation).FirstOrDefault(f => f.Sequence == "dangerous-terrain");
        if (test is null) return $"its next activation ({activation.Sequence}) took no dangerous terrain test";
        var dice = test.Steps.SelectMany(s => s.AllRolls).Sum(r => r.Dice.Count);
        var living = q.Living(grant.UnitId, test.Seq);
        return dice == 6 * living ? null : $"{dice} dice for {living} living Tough(6) models";
    }

    /// <summary>A take_test spell's tests: the spell-test frame, its target, its morale test's consequence step and whether it failed.</summary>
    static IReadOnlyList<(LoggedFrame Frame, Guid Target, LoggedStep Test, bool Failed)> Tests(LogQueries q, string spell) =>
        [.. SpellGames.Casts(q, spell).Where(c => c.Passed).SelectMany(c => q.Children(c.Frame).Where(f => f.Sequence == "spell-test")).Select(f =>
        {
            var test = q.Children(f).Single(m => m.Sequence == "morale-test").Steps.Single(s => s.Name == "consequence");
            return (f, f.Context.TargetUnitIds[0], test, test.Step.Values?.GetValueOrDefault("passed", 1) == 0);
        })];

    /// <summary>Both outcomes, as the seed rolls them.</summary>
    static string? BothOutcomes(IReadOnlyList<(LoggedFrame Frame, Guid Target, LoggedStep Test, bool Failed)> tests) =>
        tests.Any(t => t.Failed) && tests.Any(t => !t.Failed) ? null : $"{tests.Count(t => t.Failed)} of {tests.Count} tests failed; the seed must give both outcomes";

    /// <summary>Terrifying Fury: a failed test leaves the target Shaken and fatigued; a passed one makes it neither.</summary>
    static string? TerrifyingFury(LogQueries q)
    {
        var tests = Tests(q, "Terrifying Fury");
        return LogQueries.Each(tests, "Terrifying Fury test", t =>
        {
            bool Sets(LoggedStep s, string condition) => s.Step.Changes.OfType<ConditionSet>().Any(c => c.Subject.Id == t.Target && c.Condition == condition && c.Present);
            var consequence = t.Frame.Steps.Single(s => s.Name == "consequence");
            return t.Failed && !(Sets(t.Test, "shaken") && Sets(consequence, "fatigued")) ? "a failed test did not leave the target Shaken and fatigued"
                : !t.Failed && Sets(consequence, "fatigued") ? "a passed test made the target fatigued" : null;
        }) ?? BothOutcomes(tests);
    }

    /// <summary>Deep Hypnosis: a failed test offers the caster's side one move of the target's models, up to 6"; a passed one offers none.</summary>
    static string? DeepHypnosis(LogQueries q)
    {
        var tests = Tests(q, "Deep Hypnosis");
        return LogQueries.Each(tests, "Deep Hypnosis test", t =>
        {
            var moves = q.Asks.Where(a => a.Frame == t.Frame && a.Ask.Question == "move").ToList();
            if (!t.Failed) return moves.Count > 0 ? "a passed test offered a move" : null;
            if (moves.Count != 1 || moves[0].Ask.Legal is not MoveRegion region) return $"a failed test offered {moves.Count} moves";
            return Math.Abs(region.Allowance - 6) > 0.001 || !region.ModelIds.All(m => q.UnitOf(m) == t.Target)
                ? $"the move allows {region.Allowance}\" over models not all the target's" : null;
        }) ?? BothOutcomes(tests);
    }
}
